mapper.select:
SELECT * FROM ( SELECT t1.name AS procedureStepName, t1.active_time AS startTime, t1.update_by AS auditUserId, t1.complete_time, t1.flow_state, t2.node_function, t3.name AS procedureName, t1.process_change_number, t1.procedure_change_number, ROW_NUMBER() OVER (PARTITION BY t1.process_change_number, t1.procedure_change_number, t1.procedure_step_model_id ORDER BY t1.create_time DESC) AS rn FROM bm_procedure_task_instance_history t1 JOIN bm_procedure_step_model t2 ON t1.procedure_step_model_id = t2.id JOIN bm_procedure_model t3 ON t2.procedure_model_id = t3.id WHERE t1.is_deleted = 0 AND t2.is_deleted = 0 AND (t2.node_function = '1' OR t2.node_function = '2') AND t1.plan_id = #{productPlanId}
AND t3.name LIKE concat('%', #{procedureName}, '%')
AND t1.name LIKE concat('%', #{procedureStepName}, '%')
) t WHERE t.rn = 1
order by ${orderBy} ${dir}
ORDER BY startTime DESC;

select count(t1.id) as auditingCount,t1.plan_id as id from bm_procedure_task_instance_history t1 left join bm_procedure_step_model t2 on t1.procedure_step_model_id = t2.id where t1.is_deleted = 0 and t2.is_deleted = 0 and (t2.node_function = '1' or t2.node_function = '2') and t1.flow_state != 'COMPLETE' and t1.plan_id in
#{planId}
GROUP BY t1.plan_id
